139	// NotExpr represents a logical negation of a condition.
140	type NotExpr struct {
141		baseCondition
142		cond Condition
143	}
144	
145	// Cond returns the negated condition.
146	func (n *NotExpr) Cond() Condition { return n.cond }
147	
148	// Not creates a logical NOT of a condition.
149	func Not(cond Condition) *NotExpr {
150		return &NotExpr{cond: cond}
151	}
