238	func (p *StringParam) RequiredImports() []string {
239		if p.minLen != nil || p.maxLen != nil {
240			return []string{"strings"}
241		}
242		return nil
243	}
244	
245	// NotEmpty adds a non-empty string constraint.
246	// This generates CUE like: string & !=""
247	func (p *StringParam) NotEmpty() *StringParam {
248		p.notEmpty = true
249		return p
250	}
251	
252	// GetNotEmpty returns whether the non-empty constraint is set.
253	func (p *StringParam) GetNotEmpty() bool {
254		return p.notEmpty
255	}
