257	// Concat creates a string concatenation expression.
258	// Example: name.Concat("-suffix") generates: parameter.name + "-suffix"
259	func (p *StringParam) Concat(suffix string) Value {
260		return &ParamConcatExpr{paramName: p.name, suffix: suffix}
261	}
262	
263	// Prepend creates a string concatenation expression with a prefix.
264	// Example: name.Prepend("prefix-") generates: "prefix-" + parameter.name
265	func (p *StringParam) Prepend(prefix string) Value {
266		return &ParamConcatExpr{paramName: p.name, prefix: prefix}
267	}
