269	// --- StringParam Runtime Condition Methods ---
270	
271	// Contains creates a condition that checks if this string parameter contains a substring.
272	// Example: name.Contains("prod") generates: strings.Contains(parameter.name, "prod")
273	func (p *StringParam) Contains(substr string) Condition {
274		return &StringContainsCondition{paramName: p.name, substr: substr}
275	}
276	
277	// Matches creates a condition that checks if this string parameter matches a regex pattern.
278	// Example: name.Matches("^prod-") generates: parameter.name =~ "^prod-"
279	func (p *StringParam) Matches(pattern string) Condition {
280		return RegexMatch(p, pattern)
281	}
282	
283	// StartsWith creates a condition that checks if this string parameter starts with a prefix.
284	// Example: name.StartsWith("prod-") generates: strings.HasPrefix(parameter.name, "prod-")
285	func (p *StringParam) StartsWith(prefix string) Condition {
286		return &StringStartsWithCondition{paramName: p.name, prefix: prefix}
287	}
288	
289	// EndsWith creates a condition that checks if this string parameter ends with a suffix.
290	// Example: name.EndsWith("-prod") generates: strings.HasSuffix(parameter.name, "-prod")
291	func (p *StringParam) EndsWith(suffix string) Condition {
292		return &StringEndsWithCondition{paramName: p.name, suffix: suffix}
293	}
294	
295	// LenEq creates a condition that checks if this string parameter has exactly n characters.
296	// Example: name.LenEq(5) generates: len(parameter.name) == 5
297	func (p *StringParam) LenEq(n int) Condition {
298		return &LenCondition{paramName: p.name, op: "==", length: n}
299	}
300	
301	// LenGt creates a condition that checks if this string parameter has more than n characters.
302	// Example: name.LenGt(5) generates: len(parameter.name) > 5
303	func (p *StringParam) LenGt(n int) Condition {
304		return &LenCondition{paramName: p.name, op: ">", length: n}
305	}
306	
307	// LenGte creates a condition that checks if this string parameter has n or more characters.
308	// Example: name.LenGte(5) generates: len(parameter.name) >= 5
309	func (p *StringParam) LenGte(n int) Condition {
310		return &LenCondition{paramName: p.name, op: ">=", length: n}
311	}
312	
313	// LenLt creates a condition that checks if this string parameter has fewer than n characters.
314	// Example: name.LenLt(5) generates: len(parameter.name) < 5
315	func (p *StringParam) LenLt(n int) Condition {
316		return &LenCondition{paramName: p.name, op: "<", length: n}
317	}
318	
319	// LenLte creates a condition that checks if this string parameter has n or fewer characters.
320	// Example: name.LenLte(5) generates: len(parameter.name) <= 5
321	func (p *StringParam) LenLte(n int) Condition {
322		return &LenCondition{paramName: p.name, op: "<=", length: n}
323	}
324	
325	// In creates a condition that checks if this string parameter is one of the given values.
326	// Example: name.In("api", "web", "worker") generates: parameter.name == "api" || parameter.name == "web" || parameter.name == "worker"
327	func (p *StringParam) In(values ...string) Condition {
328		anyVals := make([]any, len(values))
329		for i, v := range values {
330			anyVals[i] = v
331		}
332		return &InCondition{paramName: p.name, values: anyVals}
333	}
