19	// Render executes the component template with the given test context
20	// and returns the rendered primary output resource.
21	func (c *ComponentDefinition) Render(ctx *TestContextBuilder) *RenderedResource {
22		// Build the runtime context
23		rtCtx := ctx.Build()
24	
25		// Set up the current test context for parameter resolution
26		setCurrentTestContext(rtCtx)
27		defer clearCurrentTestContext()
28	
29		// Create and execute template
30		tpl := NewTemplate()
31		if c.template != nil {
32			c.template(tpl)
33		}
34	
35		// Render the output resource with resolved values
36		return renderResource(tpl.output, rtCtx)
37	}
38	
39	// RenderAll executes the component template and returns all outputs.
40	func (c *ComponentDefinition) RenderAll(ctx *TestContextBuilder) *RenderedOutputs {
41		rtCtx := ctx.Build()
42		setCurrentTestContext(rtCtx)
43		defer clearCurrentTestContext()
44	
45		tpl := NewTemplate()
46		if c.template != nil {
47			c.template(tpl)
48		}
49	
50		outputs := &RenderedOutputs{
51			Primary:   renderResource(tpl.output, rtCtx),
52			Auxiliary: make(map[string]*RenderedResource),
53		}
54	
55		for name, res := range tpl.outputs {
56			// Check if the resource has an output condition
57			if res.outputCondition != nil {
58				if !evaluateCondition(res.outputCondition, rtCtx) {
59					// Condition is false, skip this output
60					continue
61				}
62			}
63			outputs.Auxiliary[name] = renderResource(res, rtCtx)
64		}
65	
66		return outputs
67	}
