142	// processOp processes a single resource operation.
143	func processOp(data map[string]any, op ResourceOp, ctx *TestRuntimeContext) {
144		switch o := op.(type) {
145		case *SetOp:
146			value := resolveValue(o.value, ctx)
147			setNestedValue(data, o.path, value)
148	
149		case *SetIfOp:
150			if evaluateCondition(o.cond, ctx) {
151				value := resolveValue(o.value, ctx)
152				setNestedValue(data, o.path, value)
153			}
154	
155		case *IfBlock:
156			if evaluateCondition(o.cond, ctx) {
157				for _, innerOp := range o.ops {
158					processOp(data, innerOp, ctx)
159				}
160			}
161		}
162	}
