164	// resolveValue resolves a Value to its actual value using the test context.
165	func resolveValue(v Value, ctx *TestRuntimeContext) any {
166		if v == nil {
167			return nil
168		}
169	
170		switch val := v.(type) {
171		case *StringParam:
172			return ctx.GetParamOr(val.Name(), val.GetDefault())
173		case *IntParam:
174			return ctx.GetParamOr(val.Name(), val.GetDefault())
175		case *BoolParam:
176			return ctx.GetParamOr(val.Name(), val.GetDefault())
177		case *FloatParam:
178			return ctx.GetParamOr(val.Name(), val.GetDefault())
179		case *ArrayParam:
180			return ctx.GetParamOr(val.Name(), val.GetDefault())
181		case *MapParam:
182			return ctx.GetParamOr(val.Name(), val.GetDefault())
183		case *StructParam:
184			return ctx.GetParamOr(val.Name(), val.GetDefault())
185		case *EnumParam:
186			return ctx.GetParamOr(val.Name(), val.GetDefault())
187		case *ContextRef:
188			return resolveContextRef(val, ctx)
189		case *Literal:
190			return val.Val()
191		case *TransformedValue:
192			// Resolve the source value, then apply the transformation
193			sourceValue := resolveValue(val.source, ctx)
194			if val.transform != nil {
195				return val.transform(sourceValue)
196			}
197			return sourceValue
198		case *CollectionOp:
199			// Resolve source and apply collection operations
200			sourceValue := resolveValue(val.source, ctx)
201			return applyCollectionOps(sourceValue, val.ops)
202		case *MultiSource:
203			// Combine items from multiple fields and apply operations
204			return resolveMultiSource(val, ctx)
205		case *StringKeyMapParam:
206			return ctx.GetParamOr(val.Name(), val.GetDefault())
207		default:
208			// For any Param interface, use method access
209			if p, ok := v.(Param); ok {
210				return ctx.GetParamOr(p.Name(), p.GetDefault())
211			}
212			return v
213		}
214	}
