216	// resolveContextRef resolves a context reference to its value.
217	func resolveContextRef(ref *ContextRef, ctx *TestRuntimeContext) any {
218		switch ref.Path() {
219		case "context.name":
220			return ctx.Name()
221		case "context.namespace":
222			return ctx.Namespace()
223		case "context.appName":
224			return ctx.AppName()
225		case "context.appRevision":
226			return ctx.AppRevision()
227		default:
228			return ref.String()
229		}
230	}
