483	// generateParameterBlock generates the parameter schema at the specified depth.
484	func (g *CUEGenerator) generateParameterBlock(c *ComponentDefinition, depth int) string {
485		var sb strings.Builder
486		indent := strings.Repeat(g.indent, depth)
487	
488		sb.WriteString(fmt.Sprintf("%sparameter: {\n", indent))
489	
490		for _, param := range c.GetParams() {
491			g.writeParam(&sb, param, depth+1)
492		}
493	
494		// Write top-level validators
495		for _, v := range c.GetValidators() {
496			g.writeValidator(&sb, v, depth+1)
497		}
498	
499		// Write conditional parameter blocks
500		for _, block := range c.GetConditionalParamBlocks() {
501			g.writeConditionalParamBlock(&sb, block, depth+1)
502		}
503	
504		sb.WriteString(fmt.Sprintf("%s}\n", indent))
505		return sb.String()
506	}
