557	// writeConditionalParamBlock writes conditional parameter branches.
558	// Example output:
559	//
560	//	if existingResources == false {
561	//	    forceDestroy: *false | bool
562	//	}
563	//	if existingResources == true {
564	//	    forceDestroy?: bool
565	//	}
566	func (g *CUEGenerator) writeConditionalParamBlock(sb *strings.Builder, block *ConditionalParamBlock, depth int) {
567		indent := strings.Repeat(g.indent, depth)
568	
569		for _, branch := range block.Branches() {
570			condCUE := g.conditionToCUE(branch.Condition())
571			sb.WriteString(fmt.Sprintf("%sif %s {\n", indent, condCUE))
572	
573			// Write params inside the conditional block
574			for _, param := range branch.GetParams() {
575				g.writeParam(sb, param, depth+1)
576			}
577	
578			// Write validators inside the conditional block
579			for _, v := range branch.GetValidators() {
580				g.writeValidator(sb, v, depth+1)
581			}
582	
583			sb.WriteString(fmt.Sprintf("%s}\n", indent))
584		}
585	}
