587	// writeConditionalStructOp writes a conditional struct block in the output.
588	// Example output:
589	//
590	//	if parameter["replicationConfiguration"] != _|_ {
591	//	    replicationConfiguration: {
592	//	        role: parameter.replicationConfiguration.role
593	//	    }
594	//	}
595	func (g *CUEGenerator) writeConditionalStructOp(sb *strings.Builder, cs *ConditionalStructOp, depth int) {
596		indent := strings.Repeat(g.indent, depth)
597	
598		// Build the struct
599		builder := &OutputStructBuilder{}
600		cs.Builder()(builder)
601	
602		condCUE := g.conditionToCUE(cs.Cond())
603		sb.WriteString(fmt.Sprintf("%sif %s {\n", indent, condCUE))
604	
605		// Split the path into segments and open nested structs
606		parts := splitPath(cs.Path())
607		currentIndent := indent + g.indent
608		for _, part := range parts {
609			sb.WriteString(fmt.Sprintf("%s%s: {\n", currentIndent, cueLabel(part)))
610			currentIndent += g.indent
611		}
612	
613		// Write builder operations
614		for _, op := range builder.Ops() {
615			switch o := op.(type) {
616			case *structSetOp:
617				valCUE := g.valueToCUE(o.value)
618				sb.WriteString(fmt.Sprintf("%s%s: %s\n", currentIndent, cueLabel(o.field), valCUE))
619			case *structSetIfOp:
620				condStr := g.conditionToCUE(o.cond)
621				sb.WriteString(fmt.Sprintf("%sif %s {\n", currentIndent, condStr))
622				valCUE := g.valueToCUE(o.value)
623				sb.WriteString(fmt.Sprintf("%s\t%s: %s\n", currentIndent, cueLabel(o.field), valCUE))
624				sb.WriteString(fmt.Sprintf("%s}\n", currentIndent))
625			}
626		}
