		// guard, the entire validator body is duplicated under both branches.
		g.emitGuardBlocks(sb, v.GuardCondition(), indent, func(bodyIndent string) {
			g.writeValidatorBlock(sb, v, name, bodyIndent)
		})
	} else {
		g.writeValidatorBlock(sb, v, name, indent)
	}
