// writeValidatorBlock writes the `name: { "message": true; if fail { ... } }`
// body of a validator at the given indent. When the fail condition is an
// AbsentOrEmptyCondition, two false-assignment blocks are emitted (one per branch).
func (g *CUEGenerator) writeValidatorBlock(sb *strings.Builder, v *Validator, name, indent string) {
	inner := indent + g.indent
	sb.WriteString(fmt.Sprintf("%s%s: {\n", indent, name))
	sb.WriteString(fmt.Sprintf("%s%q: true\n", inner, v.Message()))
	if v.FailCondition() != nil {
		g.emitGuardBlocks(sb, v.FailCondition(), inner, func(bodyIndent string) {
			sb.WriteString(fmt.Sprintf("%s%q: false\n", bodyIndent, v.Message()))
		})
	}
	sb.WriteString(fmt.Sprintf("%s}\n", indent))
}

// emitGuardBlocks writes one or more `if <cond> { ... }` guarded blocks around
// the body produced by writeBody. For an AbsentOrEmptyCondition it emits one
// block per branch (absent branch, then set-and-empty branch), each emitting the
// same body; for any other condition it emits a single block. writeBody is
// invoked once per block with the body indent.
func (g *CUEGenerator) emitGuardBlocks(sb *strings.Builder, cond Condition, indent string, writeBody func(bodyIndent string)) {
	var conds []Condition
	if aoe, ok := cond.(*AbsentOrEmptyCondition); ok {
		conds = aoe.Branches()
	} else {
		conds = []Condition{cond}
	}
	for _, c := range conds {
		sb.WriteString(fmt.Sprintf("%sif %s {\n", indent, g.conditionToCUE(c)))
		writeBody(indent + g.indent)
		sb.WriteString(fmt.Sprintf("%s}\n", indent))
	}
